import {$,$$,on,esc,showToast} from "./dom.js";
import {appState,events} from "./state.js";
import {renderAnnotations} from "./annotations.js";
import {openLanguageDrawer} from "./language-editor.js";

const steps=[[1,"基础与消息","规则、内容、语言"],[2,"触发与受众","事件、条件、交集"],[3,"时间与频控","窗口、时区、节流"],[4,"生命周期","结束、上限、熔断"]];

function drawerShell(){return `<div class="drawer-host is-open" id="ruleDrawer"><div class="drawer-mask" data-close-drawer></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="${appState.editingRule?"编辑":"新建"}推送规则"><header class="drawer-header"><div class="drawer-title"><h2>${appState.editingRule?"编辑":"新建"}推送规则</h2><p>S12 Pro 吸乳器 · ${appState.rule.name||"未命名规则"}</p></div><button class="icon-btn" data-close-drawer>×</button></header><div class="drawer-body"><nav class="step-nav" data-anchor="step-nav">${steps.map(([id,title,sub])=>`<button class="step-item ${appState.ruleStep===id?"active":""}" data-step="${id}"><span class="step-index">${id}</span><span class="step-copy"><strong>${title}</strong><small>${sub}</small></span></button>`).join("")}</nav><section class="drawer-content" id="ruleStepContent">${renderStep()}</section></div>${footer()}</aside></div>`}
function footer(){return `<footer class="drawer-footer" data-anchor="drawer-footer"><span class="save-hint">自动保存上次编辑：刚刚</span><div class="footer-actions"><button class="el-btn" data-draft>保存草稿</button><button class="el-btn" data-prev ${appState.ruleStep===1?"disabled":""}>上一步</button>${appState.ruleStep<4?'<button class="el-btn el-btn--primary" data-next>下一步</button>':'<button class="el-btn el-btn--primary" data-enable>保存并启用</button>'}</div></footer>`}

function basicStep(){const zh=appState.message.values["zh-CN"];return `<div class="form-section"><div class="section-title"><h3>基础信息</h3><p>规则定义何时发送及向谁发送</p></div><div class="form-grid"><label class="form-row full"><span class="form-label"><i class="required">*</i>规则名称</span><input class="el-input" data-field="name" value="${esc(appState.rule.name)}" maxlength="50"><p class="form-help">2-50 字，仅后台可见。</p></label><label class="form-row"><span class="form-label"><i class="required">*</i>产品</span><div class="readonly-field">S12 Pro 吸乳器 · 1764579849076604930</div></label><label class="form-row"><span class="form-label"><i class="required">*</i>消息分类</span><select class="el-select" data-field="category">${["安全","维护","耗材","通知","系统","固件","安防"].map(v=>`<option ${v===appState.rule.category?"selected":""}>${v}</option>`).join("")}</select></label><div class="form-row full" data-anchor="priority-field"><span class="form-label"><i class="required">*</i>优先级</span><div class="radio-row">${[["P0","紧急","关键市场语言完整才可启用"],["P1","重要","允许英文 fallback 并提示"],["P2","常规","默认常规消息"]].map(([v,t,d])=>`<label class="choice-card ${appState.rule.priority===v?"selected":""}"><input type="radio" name="priority" value="${v}" ${appState.rule.priority===v?"checked":""}><span class="choice-copy"><strong>${v} · ${t}</strong><small>${d}</small></span></label>`).join("")}</div></div></div></div><div class="form-section" data-anchor="message-editor"><div class="section-title"><h3>推送消息</h3><p>规则内维护，不创建独立模板</p></div><div class="form-grid"><label class="form-row full"><span class="form-label"><i class="required">*</i>推送标题（简体中文）</span><input class="el-input" data-message-key="title" value="${esc(zh.title)}" maxlength="100"></label><label class="form-row full"><span class="form-label"><i class="required">*</i>推送内容（简体中文）</span><textarea class="el-textarea" data-message-key="body" maxlength="200">${esc(zh.body)}</textarea><p class="form-help">支持 {{deviceName}} 等结构化占位符。</p></label><label class="form-row full"><span class="form-label">跳转页面</span><input class="el-input" data-message-link value="${esc(appState.message.cozyLink)}"><p class="form-help">支持 {id} 在发送时替换。</p></label><div class="form-row full" data-anchor="language-entry"><div class="help-alert">当前多语言完成度：<strong>3/4</strong>；美国、德国市场且 P0 时，英文与德语必须完整。</div><button class="el-btn" data-open-language>编辑多语言 KV 矩阵</button><p class="form-help">列表操作列也提供同一入口，避免引入独立模板管理。</p></div></div></div>`}

function triggerDetail(){const r=appState.rule;if(r.triggerType==="device")return `<label class="form-row full"><span class="form-label"><i class="required">*</i>设备触发条件</span><select class="el-select" data-field="deviceCondition"><option ${r.deviceCondition.includes("溢奶")?"selected":""}>溢奶事件 · level ≥ 2</option><option>吸乳时长 · ≥ 30 分钟</option><option>吸乳结束事件</option></select><p class="form-help">设备事件必须携带 deviceId；可选 userIds 作为候选用户，否则取该设备的绑定用户。</p></label>`;if(r.triggerType==="cloud")return `<label class="form-row full"><span class="form-label"><i class="required">*</i>云端触发条件</span><select class="el-select" data-field="cloudCondition"><option>喂养提醒倒计时 ≤ 30 分钟</option><option>服务订阅即将到期</option></select><p class="form-help">云端条件关联设备 deviceId；可选 userIds，否则取设备绑定用户。</p></label>`;if(r.triggerType==="consumable")return `<label class="form-row full"><span class="form-label"><i class="required">*</i>耗材触发条件</span><select class="el-select" data-field="consumableCondition"><option>滤芯余量不足</option><option>耗材已耗尽</option></select><p class="form-help">耗材属于设备层触发：以 deviceId 解析绑定用户；也可由触发载荷携带 userIds。</p></label>`;const event=events.find(e=>e.id===r.eventId)||events[0];return `<div class="form-row full" data-anchor="event-field"><span class="form-label"><i class="required">*</i>授权事件</span><select class="el-select" data-field="eventId">${events.filter(e=>e.status==="已授权").map(e=>`<option value="${e.id}" ${e.id===event.id?"selected":""}>${e.name} · ${e.id}</option>`).join("")}</select><div class="schema-box"><div class="schema-head"><span>${event.name}</span><span>${event.caller} · 已授权至 S12 Pro</span></div><pre>${esc(event.schema)}</pre></div><p class="form-help">来源：本产品「授权事件」页中已发布且已授权的事件。事件载荷可携带 userIds；为空时以当前产品全部绑定用户作为候选集。</p><button class="op-link" data-open-events>管理授权事件</button></div>`}

function triggerStep(){return `<div class="form-section"><div class="section-title"><h3>触发条件</h3><p>四类入口均在本需求范围内</p></div><div class="form-row full" data-anchor="trigger-type"><span class="form-label"><i class="required">*</i>触发类型</span><div class="radio-row">${[["device","设备触发"],["cloud","云端触发"],["consumable","耗材触发"],["event","事件触发"]].map(([v,t])=>`<label class="choice-card ${appState.rule.triggerType===v?"selected":""}"><input type="radio" name="triggerType" value="${v}" ${appState.rule.triggerType===v?"checked":""}><span class="choice-copy"><strong>${t}</strong></span></label>`).join("")}</div></div><div class="form-grid">${triggerDetail()}</div></div><div class="form-section"><div class="section-title"><h3>受众筛选</h3><p>候选用户与筛选条件独立，最终取交集</p></div><div class="form-grid"><div class="form-row full" data-anchor="candidate-users"><span class="form-label">触发载荷中的候选用户</span><div class="readonly-field">设备 / 云端 / 耗材：userIds 有值取其集合，否则取 deviceId 的绑定用户；事件：userIds 有值取其集合，否则取产品全部绑定用户。</div><p class="form-help">单点 userId 使用单元素数组；批量 userId 使用数组。规则侧不手工维护接收人名单。</p></div><div class="form-row full" data-anchor="audience-filter"><span class="form-label">用户条件筛选（可选）</span><div class="check-row">${[["活跃用户","activeStatus=true"],["绑定状态：已绑定","bindingType=bound"],["美国市场","region=US"],["德国市场","region=DE"]].map(([v,code])=>`<label><input type="checkbox" name="filters" value="${v}" ${appState.rule.filters.includes(v)?"checked":""}> ${v}</label>`).join("")}</div><p class="form-help">条件仅使用白名单字段（region、bindingType、activeStatus 等），不允许以 userId 作为筛选字段。</p></div><div class="form-row full" data-anchor="audience-intersection"><div class="summary-card"><h4>目标用户计算</h4><p>最终目标用户 = 触发载荷候选用户 ∩ 设备/产品绑定范围 ∩ 用户条件筛选 ∩ 生效市场。空集不报错，不发送并记录 suppressed=0。</p></div></div><div class="form-row full" data-anchor="regions-field"><span class="form-label"><i class="required">*</i>生效市场</span><div class="check-row">${["全部市场","美国","德国","日本","英国"].map(v=>`<label><input type="checkbox" name="regions" value="${v}" ${appState.rule.regions.includes(v)?"checked":""}> ${v}</label>`).join("")}</div><p class="form-help">市场参与最终交集、默认时区和 P0 关键语言校验。</p></div></div></div>`}

function timeStep(){return `<div class="form-section"><div class="section-title"><h3>生效时间</h3><p>默认使用市场时区</p></div><div class="form-grid"><div class="form-row full" data-anchor="time-field"><span class="form-label"><i class="required">*</i>时间范围</span><div class="inline-fields"><input class="el-input" value="${appState.rule.start}"><span>至</span><input class="el-input" value="${appState.rule.end}" placeholder="长期有效"></div></div><label class="form-row"><span class="form-label">循环</span><select class="el-select"><option>每日</option><option>每周一至周五</option><option>不循环</option></select></label><label class="form-row" data-anchor="timezone-field"><span class="form-label">时区</span><select class="el-select"><option>市场时区（推荐）</option><option>UTC+08:00 Asia/Shanghai</option></select><p class="form-help">多时区国家首期拆分规则。</p></label></div></div><div class="form-section"><div class="section-title"><h3>发送频控</h3><p>规则内最小发送间隔</p></div><div class="form-row full" data-anchor="throttle-field"><div class="radio-row">${[["实时","立即发送"],["小时节流","3600s，仅窗口首发"],["日节流","86400s，仅窗口首发"],["自定义","5 分钟至 7 天"]].map(([v,d])=>`<label class="choice-card ${appState.rule.throttle===v?"selected":""}"><input type="radio" name="throttle" value="${v}" ${appState.rule.throttle===v?"checked":""}><span class="choice-copy"><strong>${v}</strong><small>${d}</small></span></label>`).join("")}</div><div class="help-alert warning"><strong>节流语义：</strong>最小发送间隔内的后续事件丢弃，不合并成摘要；首期不承诺跨规则全局频控。</div></div></div><div class="summary-card" data-anchor="rule-summary"><h4>规则自然语言摘要</h4><p>${ruleSummary()}</p></div>`}

function lifecycleStep(){const missing=!appState.message.values["de-DE"].title||!appState.message.values["de-DE"].body;return `<div class="form-section"><div class="section-title"><h3>提醒生命周期</h3><p>用户确认不等于事件结束</p></div><div class="form-row full" data-anchor="lifecycle-field"><span class="form-label"><i class="required">*</i>提醒模式</span><div class="radio-row"><label class="choice-card ${appState.rule.lifecycle==="single"?"selected":""}"><input type="radio" name="lifecycle" value="single" ${appState.rule.lifecycle==="single"?"checked":""}><span class="choice-copy"><strong>单次通知</strong><small>触发后按频控发送一次</small></span></label><label class="choice-card ${appState.rule.lifecycle==="continuous"?"selected":""}"><input type="radio" name="lifecycle" value="continuous" ${appState.rule.lifecycle==="continuous"?"checked":""}><span class="choice-copy"><strong>连续提醒</strong><small>直到恢复事件或安全上限结束</small></span></label></div></div>${appState.rule.lifecycle==="continuous"?`<label class="form-row full"><span class="form-label">结束事件（恢复信号）</span><select class="el-select" data-field="recoveryEvent"><option value="">不配置 — 进入受限模式</option>${events.filter(e=>e.id.includes("recovered")).map(e=>`<option value="${e.id}" ${appState.rule.recoveryEvent===e.id?"selected":""}>${e.name} · ${e.id}</option>`).join("")}</select><p class="form-help">通过 eventId + userId/deviceId 匹配活跃提醒实例；用户点击或确认消息不会结束提醒。</p></label>`:""}<div class="help-alert ${appState.rule.recoveryEvent?"success":"warning"}">${appState.rule.recoveryEvent?"正常生命周期：已绑定恢复事件；仅匹配同一 userId/deviceId 的活跃实例。":"受限模式：未配置结束事件，必须依赖时长、次数与熔断器自动停止。"}</div></div><div class="form-section" data-anchor="hard-cap"><div class="section-title"><h3>安全上限与熔断</h3><p>系统硬顶不可按规则修改</p></div><div class="form-grid"><label class="form-row"><span class="form-label">规则最大持续时间</span><input class="el-input" type="number" value="${appState.rule.maxHours}" min="1" max="168" ${appState.rule.recoveryEvent?"disabled":""}><p class="form-help">默认 72h；系统硬顶 168h。</p></label><label class="form-row"><span class="form-label">规则最大提醒次数</span><input class="el-input" type="number" value="${appState.rule.maxCount}" min="1" max="500" ${appState.rule.recoveryEvent?"disabled":""}><p class="form-help">默认 100；系统硬顶 500。</p></label><div class="form-row full" data-anchor="delivery-cap"><div class="readonly-field">投递硬顶：1 push / 5 min / user / rule</div><p class="form-help">熔断条件：达到 duration、count 或 >100 triggers/min/rule。</p></div></div></div><div class="form-section" data-anchor="validation"><div class="section-title"><h3>保存前校验</h3><p>自动执行</p></div><div class="validation-list"><div class="validation-item"><span>✓ 规则、触发条件及事件授权</span><span class="el-tag el-tag--success is-plain">通过</span></div><div class="validation-item"><span>${missing?"!":"✓"} P0 关键市场语言（英文 + 德语）</span><span class="el-tag el-tag--${missing?"danger":"success"} is-plain">${missing?"阻断：德语缺失":"通过"}</span></div><div class="validation-item"><span>! 与“夜间溢奶安全提醒”触发范围重叠</span><button class="op-link" data-conflict>查看冲突</button></div><div class="validation-item"><span>✓ 用户目标交集、占位符与生命周期安全上限</span><span class="el-tag el-tag--success is-plain">通过</span></div></div>${missing?'<button class="el-btn" style="margin-top:10px" data-open-language>补全规则德语</button>':""}</div>`}

function renderStep(){return appState.ruleStep===1?basicStep():appState.ruleStep===2?triggerStep():appState.ruleStep===3?timeStep():lifecycleStep()}
function triggerLabel(){const r=appState.rule;if(r.triggerType==="device")return r.deviceCondition;if(r.triggerType==="cloud")return r.cloudCondition;if(r.triggerType==="consumable")return r.consumableCondition;return events.find(e=>e.id===r.eventId)?.name||r.eventId}
function ruleSummary(){return `当【${triggerLabel()}】发生时；从【触发载荷 / 绑定用户】得到候选集并与【${appState.rule.filters.join("、")}、${appState.rule.regions.join("、")}市场】取交集；在【2026-08-01 起，按市场时区每日生效】；按【${appState.rule.throttle}，${appState.rule.lifecycle==="continuous"?"连续提醒直至恢复事件":"单次通知"}】发送规则内消息。`}

export function openRuleDrawer({edit=false,onOpenEvents}={}){appState.editingRule=edit;appState.ruleStep=1;$("#overlayRoot").innerHTML=drawerShell();wire(onOpenEvents);renderAnnotations("rule1","规则配置 · 步骤 1/4")}
function rerender(onOpenEvents){$("#ruleStepContent").innerHTML=renderStep();$$(".step-item").forEach(el=>el.classList.toggle("active",Number(el.dataset.step)===appState.ruleStep));$(".drawer-footer").outerHTML=footer();wireStep(onOpenEvents);renderAnnotations(`rule${appState.ruleStep}`,`规则配置 · 步骤 ${appState.ruleStep}/4`)}
function wire(onOpenEvents){const host=$("#ruleDrawer");on(host,"click","[data-close-drawer]",()=>closeRuleDrawer());on(host,"click","[data-step]",(e,el)=>{appState.ruleStep=Number(el.dataset.step);rerender(onOpenEvents)});wireStep(onOpenEvents)}
function wireStep(onOpenEvents){const host=$("#ruleDrawer");$$('[data-field]',host).forEach(el=>el.addEventListener("change",()=>{appState.rule[el.dataset.field]=el.value;rerender(onOpenEvents)}));$$('input[name="priority"]',host).forEach(el=>el.addEventListener("change",()=>{appState.rule.priority=el.value;rerender(onOpenEvents)}));$$('input[name="triggerType"]',host).forEach(el=>el.addEventListener("change",()=>{appState.rule.triggerType=el.value;rerender(onOpenEvents)}));$$('input[name="throttle"]',host).forEach(el=>el.addEventListener("change",()=>{appState.rule.throttle=el.value;rerender(onOpenEvents)}));$$('input[name="lifecycle"]',host).forEach(el=>el.addEventListener("change",()=>{appState.rule.lifecycle=el.value;rerender(onOpenEvents)}));$$('input[name="filters"]',host).forEach(el=>el.addEventListener("change",()=>{appState.rule.filters=$$("input[name=filters]:checked",host).map(x=>x.value);rerender(onOpenEvents)}));$$('input[name="regions"]',host).forEach(el=>el.addEventListener("change",()=>{const values=$$("input[name=regions]:checked",host).map(x=>x.value);appState.rule.regions=values.includes("全部市场")?["全部市场"]:values;rerender(onOpenEvents)}));$$('[data-message-key]',host).forEach(el=>el.addEventListener("input",()=>{appState.message.values["zh-CN"][el.dataset.messageKey]=el.value}));$('[data-message-link]',host)?.addEventListener("input",e=>{appState.message.cozyLink=e.target.value});$('[data-next]',host)?.addEventListener("click",()=>{appState.ruleStep++;rerender(onOpenEvents)});$('[data-prev]',host)?.addEventListener("click",()=>{appState.ruleStep--;rerender(onOpenEvents)});$('[data-draft]',host)?.addEventListener("click",e=>saveButton(e.currentTarget,"草稿已保存"));$$('[data-open-language]',host).forEach(el=>el.addEventListener("click",()=>openLanguageDrawer({onClose:()=>rerender(onOpenEvents)})));$('[data-open-events]',host)?.addEventListener("click",()=>{closeRuleDrawer();onOpenEvents?.()});$('[data-conflict]',host)?.addEventListener("click",()=>openConflict());$('[data-enable]',host)?.addEventListener("click",e=>{const missing=!appState.message.values["de-DE"].title||!appState.message.values["de-DE"].body;if(missing){showToast("P0 规则缺少德国市场主语言，无法启用","error");return}openConflict(true,e.currentTarget)})}
function saveButton(btn,message){btn.disabled=true;btn.textContent="保存中…";setTimeout(()=>{showToast(message);btn.disabled=false;btn.textContent="保存草稿"},650)}
function openConflict(saveAfter=false){const modal=document.createElement("div");modal.className="modal-host";modal.innerHTML=`<div class="modal"><header class="modal-header"><h3>发现 1 条潜在冲突</h3><button class="icon-btn" data-modal-close>×</button></header><div class="modal-body"><div class="help-alert warning">相同触发对象、相同市场且生效时间重叠。该冲突为警告，不自动阻断。</div><div class="conflict-row"><strong>夜间溢奶安全提醒</strong><div class="secondary-cell">美国、德国 · 每日 22:00-08:00 · P0</div></div></div><footer class="modal-footer"><button class="el-btn" data-modal-close>返回修改</button>${saveAfter?'<button class="el-btn el-btn--primary" data-confirm-save>仍然启用</button>':""}</footer></div>`;document.body.appendChild(modal);$$('[data-modal-close]',modal).forEach(x=>x.onclick=()=>modal.remove());$('[data-confirm-save]',modal)?.addEventListener("click",e=>{e.currentTarget.disabled=true;e.currentTarget.textContent="保存中…";setTimeout(()=>{modal.remove();closeRuleDrawer();showToast("规则已保存并启用")},700)})}
export function closeRuleDrawer(){const host=$("#ruleDrawer");if(!host)return;host.classList.remove("is-open");setTimeout(()=>host.remove(),220);renderAnnotations(appState.tab,appState.tab==="rules"?"推送规则列表":"授权事件")}
